import type { AppState, DailyPlan, Punishment } from '../types';
import { createInitialState } from './seed';
import { getSupabase } from './supabase';

type DbUserProgress = {
  user_id: string;
  total_xp: number;
  current_level: number;
  streak: number;
  points: number;
  last_active_date: string | null;
  settings: AppState['settings'];
  daily_plans: Record<string, DailyPlan>;
  unlocked_reward_ids: string[];
  punishments: Punishment[];
};

export function userSliceFromState(state: AppState): Omit<AppState, 'categories' | 'tasks' | 'rewards' | 'punishmentTemplates' | 'videoCategories' | 'videos' | 'levels' | 'version'> {
  return {
    progress: state.progress,
    dailyPlans: state.dailyPlans,
    punishments: state.punishments,
    settings: state.settings,
    unlockedRewardIds: state.unlockedRewardIds,
  };
}

export function applyUserProgressToState(
  base: AppState,
  row: DbUserProgress,
): AppState {
  return {
    ...base,
    progress: {
      totalXp: row.total_xp,
      currentLevel: row.current_level,
      streak: row.streak,
      points: row.points,
      lastActiveDate: row.last_active_date,
    },
    dailyPlans: row.daily_plans ?? {},
    settings: row.settings ?? base.settings,
    unlockedRewardIds: row.unlocked_reward_ids ?? [],
    punishments: row.punishments ?? [],
  };
}

export async function fetchUserProgress(
  userId: string,
): Promise<{ ok: true; state: AppState } | { ok: false; error: string }> {
  const supabase = getSupabase();
  if (!supabase) return { ok: false, error: 'Supabase is not configured.' };

  const { data, error } = await supabase
    .from('user_progress')
    .select('*')
    .eq('user_id', userId)
    .maybeSingle();

  if (error) return { ok: false, error: error.message };

  const base = createInitialState();
  if (!data) {
    const { error: insertError } = await supabase.from('user_progress').insert({
      user_id: userId,
    });
    if (insertError) return { ok: false, error: insertError.message };
    return { ok: true, state: base };
  }

  return { ok: true, state: applyUserProgressToState(base, data as DbUserProgress) };
}

export async function saveUserProgress(
  userId: string,
  state: AppState,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const supabase = getSupabase();
  if (!supabase) return { ok: false, error: 'Supabase is not configured.' };

  const row = {
    user_id: userId,
    total_xp: state.progress.totalXp,
    current_level: state.progress.currentLevel,
    streak: state.progress.streak,
    points: state.progress.points,
    last_active_date: state.progress.lastActiveDate,
    settings: state.settings,
    daily_plans: state.dailyPlans,
    unlocked_reward_ids: state.unlockedRewardIds,
    punishments: state.punishments,
    updated_at: new Date().toISOString(),
  };

  const { error } = await supabase.from('user_progress').upsert(row);
  if (error) return { ok: false, error: error.message };
  return { ok: true };
}

import type { Session, UserRole } from '../types';
import { getSupabase, isSupabaseConfigured } from './supabase';

export interface AuthSession {
  userId: string;
  email: string;
  username: string;
  role: UserRole;
}

/** Map username to internal email for legacy-style usernames. */
export function usernameToEmail(username: string): string {
  const trimmed = username.trim().toLowerCase();
  if (trimmed.includes('@')) return trimmed;
  return `${trimmed}@local.app`;
}

export async function getCurrentSession(): Promise<AuthSession | null> {
  const supabase = getSupabase();
  if (!supabase) return null;

  const { data: sessionData } = await supabase.auth.getSession();
  const user = sessionData.session?.user;
  if (!user) return null;

  const { data: profile, error } = await supabase
    .from('profiles')
    .select('username, role')
    .eq('id', user.id)
    .maybeSingle();

  if (error || !profile) return null;

  return {
    userId: user.id,
    email: user.email ?? '',
    username: profile.username,
    role: profile.role as UserRole,
  };
}

export function sessionToApp(session: AuthSession): Session {
  return {
    userId: session.userId,
    username: session.username,
    role: session.role,
  };
}

// Re-export for types compatibility in Login
export type Session = AuthSession extends never ? never : import('../types').Session;

export async function login(
  emailOrUsername: string,
  password: string,
): Promise<{ ok: true; session: AuthSession } | { ok: false; error: string }> {
  if (!isSupabaseConfigured()) {
    return { ok: false, error: 'Supabase is not configured. See setup instructions on the login page.' };
  }

  const supabase = getSupabase()!;
  const email = emailOrUsername.includes('@')
    ? emailOrUsername.trim().toLowerCase()
    : usernameToEmail(emailOrUsername);

  const { error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) {
    return { ok: false, error: error.message };
  }

  const session = await getCurrentSession();
  if (!session) {
    return { ok: false, error: 'Signed in but profile not found. Ask an admin to check your account.' };
  }
  return { ok: true, session };
}

export async function logout(): Promise<void> {
  const supabase = getSupabase();
  if (supabase) await supabase.auth.signOut();
}

export async function changePassword(
  newPassword: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  if (newPassword.length < 6) {
    return { ok: false, error: 'New password must be at least 6 characters.' };
  }
  const supabase = getSupabase();
  if (!supabase) return { ok: false, error: 'Supabase is not configured.' };

  const { error } = await supabase.auth.updateUser({ password: newPassword });
  if (error) return { ok: false, error: error.message };
  return { ok: true };
}

export async function createUser(
  username: string,
  password: string,
  role: UserRole,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const trimmed = username.trim();
  if (!trimmed) return { ok: false, error: 'Username is required.' };
  if (password.length < 6) {
    return { ok: false, error: 'Password must be at least 6 characters.' };
  }

  const supabase = getSupabase();
  if (!supabase) return { ok: false, error: 'Supabase is not configured.' };

  const email = usernameToEmail(trimmed);
  const { error } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: { username: trimmed, role },
    },
  });

  if (error) {
    return {
      ok: false,
      error:
        error.message +
        ' (If sign-ups are disabled, create the user in the Supabase Dashboard → Authentication.)',
    };
  }
  return { ok: true };
}

export function onAuthStateChange(
  callback: (session: AuthSession | null) => void,
): (() => void) | undefined {
  const supabase = getSupabase();
  if (!supabase) return undefined;

  const { data } = supabase.auth.onAuthStateChange((_event, authSession) => {
    if (!authSession?.user) {
      callback(null);
      return;
    }
    void getCurrentSession().then(callback);
  });

  return () => data.subscription.unsubscribe();
}

